<section id="firmas" class="ios-card p-5"><div class="flex items-center justify-between gap-3"><h2 class="text-sm font-semibold">Firmas electrónicas</h2><?= icon('shield-plain','h-4 w-4 text-blue-500') ?></div><p class="mt-2 text-[11px] leading-5 text-slate-400">Reautenticación, consentimiento, contenido SHA-256 y sello HMAC-SHA256. No es una firma digital certificada ni una certificación de cumplimiento.</p><?php if($signatures): ?><div class="mt-4 space-y-3"><?php foreach($signatures as$signature): $check=$signature['verificacion']; ?><article class="rounded-xl border <?= $check['valida']?'border-emerald-100 bg-emerald-50/50':'border-rose-100 bg-rose-50/50' ?> p-3"><div class="flex items-start justify-between gap-2"><div><p class="text-xs font-semibold text-slate-800"><?= e($signature['firmante_nombre']??'Cuenta retirada') ?></p><p class="mt-0.5 text-[10px] text-slate-500"><?= e($signature['firmante_rol']) ?> · v<?= (int)$signature['version'] ?></p></div><span class="badge <?= $check['valida']?'badge-green':'badge-red' ?>"><?= $check['valida']?'Integridad verificada':'Revisar integridad' ?></span></div><p class="mt-2 text-[10px] text-slate-500"><?= format_date($signature['firmado_at'],true) ?> · <?= e($signature['algoritmo']) ?></p><p class="mt-2 break-all font-mono text-[9px] leading-4 text-slate-400">SHA-256: <?= e($signature['contenido_hash']) ?></p><p class="mt-1 text-[9px] <?= $check['valida']?'text-emerald-700':'text-rose-700' ?>"><?= e($check['mensaje']) ?></p></article><?php endforeach; ?></div><?php else: ?><p class="mt-4 rounded-xl bg-slate-50 p-3 text-xs text-slate-400">Esta versión no tiene firmas registradas.</p><?php endif; ?><?php if(isset($signatureConsent)&&$document['estado']==='Aprobado'): ?><?php if($canSign): ?><details class="mt-4 rounded-xl border border-slate-200 p-3"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Firmar versión <?= (int)$document['version'] ?></summary><form method="post" action="<?= e(url('/documentos/'.$document['id'].'/firmas')) ?>" class="mt-3 space-y-3"><?= csrf_field() ?><div><label class="label">Contraseña actual *</label><input type="password" name="password" class="input" required autocomplete="current-password"></div><label class="flex items-start gap-2 text-[10px] leading-4 text-slate-600"><input type="checkbox" name="consentimiento" value="1" class="mt-0.5" required><span><?= e($signatureConsent) ?></span></label><p class="break-all rounded-lg bg-slate-50 p-2 font-mono text-[9px] text-slate-400"><?= e($currentContentHash) ?></p><button class="btn-primary w-full" type="submit"><?= icon('edit','h-4 w-4') ?> Firmar esta versión</button></form></details><?php else: ?><p class="mt-3 text-[10px] text-amber-600">Tu cuenta necesita el permiso documentos.firmar.</p><?php endif; ?><?php endif; ?></section>
